-- AS3935 demo station for stratusweather.co.za
-- Generated from potchefstroom_full_demo.dat: 2304 readings, 30 channels
-- Stored window 2026-08-12 02:50:00 .. 2026-08-20 02:45:00 UTC (file times shifted -2 h from SAST)
--
-- Demo only. connection_type='demo' keeps every live-data path away from
-- it, and connection_config is empty so no uplink identifier can resolve
-- to it. Do NOT call POST /api/stations/cleanup: that endpoint deletes
-- any station whose connection_type is 'demo'.

BEGIN;

-- The station id is held in a temp table rather than a plpgsql variable so
-- the readings below can be plain batched INSERTs instead of one enormous
-- procedure body.
CREATE TEMP TABLE _as3935_sid (id integer) ON COMMIT DROP;

-- Create the station only if it is not already there.
    connection_config, is_active, latitude, longitude, altitude,
    location, site_description, notes, protocol, station_type)
SELECT 'AS3935', 1, 'demo', '{}'::jsonb, true,
       -26.7145, 27.0977, 1350.0,
       'Potchefstroom, North West, South Africa',
       'Demonstration station. AS3935 lightning detector plus a full weather sensor suite. Synthetic data, no live feed.',
       'DEMO ONLY - the readings are generated, not measured. Site geometry is the Potchefstroom standard: -26.7145, 27.0977, 1350 m AMSL.',
       'pakbus', 'http'
 WHERE NOT EXISTS (SELECT 1 FROM stations WHERE name = 'AS3935');


-- Keep the site geometry authoritative even on a re-run, and make sure the
-- station stays inert.
UPDATE stations SET
    latitude = -26.7145, longitude = 27.0977, altitude = 1350.0,
    location = 'Potchefstroom, North West, South Africa',
    connection_type = 'demo', connection_config = '{}'::jsonb,
    is_active = true, updated_at = CURRENT_TIMESTAMP
  WHERE id = (SELECT id FROM _as3935_sid);

-- Replace any previous seed so re-running cannot leave stale readings.
DELETE FROM weather_data
 WHERE station_id = (SELECT id FROM _as3935_sid)
   AND table_name = 'WeatherData';

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

ON CONFLICT (station_id, table_name, timestamp) DO UPDATE
  SET data = EXCLUDED.data, collected_at = CURRENT_TIMESTAMP;

-- Reflect the newest reading on the station row.
UPDATE stations SET last_connected = (
    SELECT MAX(timestamp) FROM weather_data
     WHERE station_id = (SELECT id FROM _as3935_sid))
  WHERE id = (SELECT id FROM _as3935_sid);

COMMIT;

-- Verification
SELECT s.id, s.name, s.connection_type, s.latitude, s.longitude, s.altitude,
       count(w.id) AS readings,
       min(w.timestamp) AS earliest, max(w.timestamp) AS latest
  FROM stations s LEFT JOIN weather_data w ON w.station_id = s.id
 WHERE s.name = 'AS3935'
 GROUP BY s.id, s.name, s.connection_type, s.latitude, s.longitude, s.altitude;

-- Lightning must be present: this is what the whitelist in the import
-- endpoint would have discarded.
SELECT count(*) FILTER (WHERE data ? 'lightning')          AS has_lightning,
       count(*) FILTER (WHERE data ? 'lightningDistance')  AS has_distance,
       count(*) FILTER (WHERE data ? 'lightningEnergy')    AS has_energy,
       max((data->>'lightning')::numeric)                  AS strike_counter,
       min((data->>'lightningDistance')::numeric)          AS closest_km,
       max((data->>'lightningEnergy')::numeric)            AS peak_energy
  FROM weather_data
 WHERE station_id = (SELECT id FROM stations WHERE name = 'AS3935');
